import { getPersons, createPerson } from "../components/apiutils";
import Nav from "../components/Nav";
import {useState,useEffect} from "react";


export default function UserMgmt(){
    const [users, setUsers] = useState([]);
    const [formData, setFormData] = useState({ name: "", email: "", mobile: "" });

    useEffect(()=>{
        getPersons()
        .then((users)=>{
            setUsers(users)
        })
        .catch((error) => {
            console.error("Failed to load users:", error);
        })
    },[]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData((prev) => ({
            ...prev,
            [name]: value
        }));
    };

    const handleFormSubmit = (e) => {
        e.preventDefault();
        
        // Add the new user to the table immediately
        const newUser = {
            name: formData.name,
            email: formData.email,
            mobile: formData.mobile
        };
        
        setUsers((prevUsers) => [...prevUsers, newUser]);
        
        // Also send to backend
        createPerson(formData)
            .then((response) => {
                console.log("User created successfully", response);
            })
            .catch((error) => {
                console.error("Failed to create user:", error);
            });
        
        // Clear the form
        setFormData({ name: "", email: "", mobile: "" });
    };

    return <>
    <Nav>
        <div style={{ padding: "20px" }}>
            <form onSubmit={handleFormSubmit} style={{ marginBottom: "30px", border: "1px solid #ccc", padding: "20px" }}>
                <h3>Add New User</h3>
                <div style={{ marginBottom: "10px" }}>
                    <label>Name: </label>
                    <input 
                        type="text" 
                        name="name" 
                        value={formData.name} 
                        onChange={handleInputChange} 
                        required 
                    />
                </div>
                <div style={{ marginBottom: "10px" }}>
                    <label>Email: </label>
                    <input 
                        type="email" 
                        name="email" 
                        value={formData.email} 
                        onChange={handleInputChange} 
                        required 
                    />
                </div>
                <div style={{ marginBottom: "10px" }}>
                    <label>Mobile: </label>
                    <input 
                        type="text" 
                        name="mobile" 
                        value={formData.mobile} 
                        onChange={handleInputChange} 
                        required 
                    />
                </div>
                <button type="submit">Submit</button>
            </form>

            <h3>Users List</h3>
            <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                    <tr style={{ borderBottom: "2px solid #000" }}>
                        <th style={{ padding: "10px", textAlign: "left" }}>Name</th>
                        <th style={{ padding: "10px", textAlign: "left" }}>Email</th>
                        <th style={{ padding: "10px", textAlign: "left" }}>Phone</th>
                    </tr>
                </thead>
                <tbody>
                    {users.map((user, index)=>{
                        return <tr key={index} style={{ borderBottom: "1px solid #ddd" }}>
                            <td style={{ padding: "10px" }}>{user.name}</td>
                            <td style={{ padding: "10px" }}>{user.email}</td>
                            <td style={{ padding: "10px" }}>{user.mobile}</td> 
                        </tr>
                    })}
                </tbody>
            </table>
        </div>
    </Nav>
    </>
}
